// Shared mock state keeps every workspace on the same sequence.
const studioDefaults=()=>({fps:24,aspect:'16:9',resolution:1080,post:'color',postTab:'basic',search:'files',deleted:[],assetEdits:{},projectSaved:null,recent:['Claude Mouse','Leeres Projekt'],settings:'general',providers:{'fal.ai':true,Runway:true,ElevenLabs:true},disabledModels:[],backend:'Embedded Claude',ready:true,connections:[],packVersion:'Projektversion',packAvailable:true,uiScale:100,notify:true,telemetry:false,index:true,queryHistory:[],activity:[],task:null,clipboard:null,viewerZoom:1,compare:false,theater:false,range:[0,3],takeReviews:{},takeFocus:1,entities:[],entity:0,refCategory:'Alle',intakeItems:[],intakeType:'Figur',analysisQuality:'Gemessen',patterns:'Erzählbogen',modelEvidence:false,modelResearch:null,history:[],historyIndex:-1,exportRetry:false});
const SX=(a,label,opts={})=>B('studio:'+a,label,opts);
const SXI=(a,icon,label,pressed=null)=>SX(a,NI(icon),{cls:'nle-icon',attrs:`aria-label="${E(label)}" data-tooltip="${E(label)}" ${pressed===null?'':`aria-pressed="${pressed}"`}`});
const sxInput=(label,key,value,type='text',attrs='')=>`<label class="property"><span>${E(label)}</span><input data-sx="${key}" type="${type}" value="${E(value)}" ${attrs}></label>`;
const sxSelect=(label,key,value,items)=>`<label class="property"><span>${E(label)}</span><select data-sx="${key}">${items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${E(v)}" ${String(value)===String(v)?'selected':''}>${E(t)}</option>`;}).join('')}</select></label>`;
const sxCheck=(label,key,value)=>`<label class="finish-check"><input type="checkbox" data-sx="${key}" ${value?'checked':''}><span>${E(label)}</span></label>`;
const settingsRow=(label,controls)=>`<div class="settings-row"><span class="settings-label">${E(label)}</span><div class="settings-controls">${controls}</div></div>`;
function studioEnsure(){S.studio??=studioDefaults();for(const [k,v]of Object.entries(studioDefaults()))S.studio[k]??=clone(v);if(S.studio.task?.kind==='model'){S.studio.modelResearch=S.studio.task;S.studio.task=null;}S.postSection??='color';if(!S.studio.entities.length&&S.identities)S.studio.entities=[['Claude Mouse','Figuren',1],['AI Cat','Figuren',2],['Dorfbewohner','Ensembles',5],['Straße','Orte',0],['Comfort Engine','Props',4],['Staubiges Morgenlicht','Look',0]].map(([name,type,pic])=>({name,type,pic,attributes:{Kleidung:'Unverändert',Licht:'Morgen',Material:'Matt'},locked:['Kleidung']}));}
const studioAudit=(title,detail='')=>{S.studio.activity.unshift({title,detail,version:S.version,view:/Videolauf|Takes freigegeben/.test(title)?'takes':S.view,shotID:shot()?.id,post:S.studio.post,time:new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})});S.studio.activity=S.studio.activity.slice(0,40);};
function studioCommit(message){S.notice=message;render();persist();}
const clipName=c=>c?.name||(S.shots[c?.shot]?S.shots[c.shot].id+(c?.take?' · Take '+c.take:''):'Sequenz 01');
const clipImage=c=>c?.asset?assetImage(assets().find(a=>a.id===c.asset)||{name:c.name,type:c.type||'image'}):pic(c?.shot??0,'reference');
const frameDuration=c=>c?.sourceDuration||S.shots[c?.shot]?.duration||Math.max(5,c?.out||0);
const clipDefaults=()=>({in:0,out:5,start:0,scale:100,x:0,y:0,opacity:100,speed:1,exposure:0,saturation:100,rotation:0,flipX:false,flipY:false,crop:0,gain:0,fadeIn:0,fadeOut:0,track:'V1',keys:[],fx:{},bypass:false});
const syncPair=()=>{const v=selectedClips().filter(c=>c.type!=='audio'),a=selectedClips().filter(c=>c.type==='audio');return v.length===1&&a.length===1?{video:v[0],audio:a[0]}:null;};
const clipEditable=c=>!!c&&!S.running&&!S.nle.tracks.find(t=>t.id===c.track)?.lock;
const titleEditable=()=>!S.running&&!S.nle.tracks.find(t=>t.id===(S.nle.titles[S.studio.titleIndex||0]?.track||'V2'))?.lock;
const clipActions=['key-add','key-delete','grade-reset','load-lut','lut-confirm','swap','swap-confirm','color-match','word-cut'];
const montageActions=['paste','duplicate','delete','ripple','close-gaps','link','swap','swap-confirm','insert','overwrite'];
function parameterValue(c,k,time=S.nle.cursor){const keys=c.keys.filter(x=>x.key===k).sort((a,b)=>a.time-b.time),t=time-c.start;if(!keys.length)return c[k];const a=keys.filter(x=>x.time<=t).at(-1)||keys[0],b=keys.find(x=>x.time>t);if(!b||a.interpolation==='Hold')return a.value;let u=Math.max(0,Math.min(1,(t-a.time)/(b.time-a.time)));if(a.interpolation==='Ease In')u*=u;if(a.interpolation==='Ease Out')u=1-(1-u)**2;if(a.interpolation==='Ease In/Out')u=u*u*(3-2*u);return a.value+(b.value-a.value)*u;}
function parameterSet(c,k,value){if(!c.keys.some(x=>x.key===k)){c[k]=value;return;}const time=Math.max(0,Math.min(nleLength(c),S.nle.cursor-c.start)),x=c.keys.find(x=>x.key===k&&Math.abs(x.time-time)<1/fps());if(x)x.value=value;else c.keys.push({key:k,time,value,interpolation:'Linear'});}
function selectTitle(i){const n=S.nle;if(!n.titles[i])return;stop();n.selected=null;n.marked=[];n.selectedTitle=i;S.studio.titleIndex=i;S.studio.selectedKey=null;S.mediaPreview=false;const t=n.titles[i];if(n.cursor<t.start||n.cursor>=t.end)n.cursor=t.start;if(S.view==='post')S.studio.post=t.caption?'captions':'titles';else n.tab=t.caption?'captions':'titles';render();persist();}
const originalEnsureNLE=ensureNLE;
ensureNLE=function(){studioEnsure();originalEnsureNLE();if(!S.nle)S.nle={clips:[],audioLength:0,selected:null,cursor:0,sourceCursor:0,tool:'pointer',zoom:1,tab:'video',hidden:false,muted:false,gain:0,titles:[],height:270,nextId:0};const n=S.nle;n.tracks??=[{id:'V2',type:'video',hidden:false,lock:false,sync:true},{id:'V1',type:'video',hidden:false,lock:false,sync:true},{id:'A1',type:'audio',hidden:false,lock:false,sync:true}];n.marked??=n.selected?[n.selected]:[];n.selectedTitle??=null;n.titles.forEach(t=>t.track??='V2');n.snap??=true;n.range??=[0,3];n.clips.forEach(c=>{for(const [k,v]of Object.entries(clipDefaults()))c[k]??=clone(v);c.name??=S.shots[c.shot]?.id+' · Take '+c.take;if(c.shot!==undefined&&c.take)c.asset??=activeTakeAssetID(c.shot,c.take);});if(n.audioLength&&!n.audioMigrated){n.clips.push({...clipDefaults(),id:'track-song',asset:S.trackMediaId||'track',name:'Claude-mouse.wav',type:'audio',track:'A1',out:n.audioLength,sourceDuration:n.audioLength});n.audioMigrated=true;}n.audioLength=0;};
function studioVisualAt(t){return S.nle.clips.filter(c=>c.type!=='audio'&&!S.nle.tracks.find(x=>x.id===c.track)?.hidden&&t>=c.start&&t<c.start+nleLength(c)).sort((a,b)=>S.nle.tracks.findIndex(x=>x.id===a.track)-S.nle.tracks.findIndex(x=>x.id===b.track))[0];}
function studioPicture(c,time=0,viewer=false,showTitles=true){if(!c)return '<div class="studio-black">Keine Bildquelle an dieser Position</div>';const f=c.bypass?{}:c.fx;const aspect=S.studio.aspect.split(':').map(Number);const exposure=c.bypass?0:c.exposure, saturation=c.bypass?100:c.saturation;const key=(k,v)=>parameterValue(c,k,time)??v;return `<div class="studio-picture ${viewer&&showTitles&&S.studio.canvasEdit?'studio-positioning':''}" ${showTitles?'data-picture-drag':''} style="max-width:${aspect[0]/aspect[1]*(S.studio.theater?640:370)}px;--picture-aspect:${aspect[0]/aspect[1]};aspect-ratio:${S.studio.aspect.replace(':','/')};--clip-scale:${key('scale',c.scale)/100*(viewer?S.studio.viewerZoom:1)};--clip-x:${key('x',c.x)}%;--clip-y:${key('y',c.y)}%;--clip-rotate:${c.rotation}deg;--clip-opacity:${key('opacity',c.opacity)/100};--clip-flip-x:${c.flipX?-1:1};--clip-flip-y:${c.flipY?-1:1};--clip-crop:${c.crop}%;--clip-filter:brightness(${2**exposure}) contrast(${1+(f.contrast||0)/100}) saturate(${saturation/100}) blur(${(f.blur||0)/8}px) sepia(${Math.max(0,(f.temperature||0))/150})"><div class="studio-image">${clipImage(c)}</div>${f.vignette?`<div class="studio-vignette" style="opacity:${f.vignette/100}"></div>`:''}${(showTitles?S.nle.titles:[]).filter(x=>time>=x.start&&time<x.end&&!S.nle.tracks.find(t=>t.id===(x.track||'V2'))?.hidden).map(x=>`<div class="studio-caption" style="color:${x.color||'#ffffff'};background:${x.background?'#111b':'transparent'};font-family:${E(x.font||'system-ui')};font-size:${x.size||24}px;text-align:${x.align||'center'};bottom:${x.y??8}%;text-shadow:${x.shadow?'2px 2px 3px #000':'none'};-webkit-text-stroke:${x.outline?'.5px #111':'0'}">${E(x.text)}</div>`).join('')}</div>`;}
function studioSequenceViewer(){const source=S.mediaPreview?selectedAsset():null,c=source?{...clipDefaults(),asset:source.id,name:source.name}:studioVisualAt(S.nle.cursor),compare=!source&&S.studio.compare,timed=!source||source.type==='video';return `<div class="studio-viewer ${compare?'studio-comparison':''}">${compare&&c?`<div><small>Original</small>${studioPicture({...c,bypass:true},S.nle.cursor,true)}</div>`:''}<div>${compare?`<small>Bearbeitet</small>`:''}${studioPicture(c,nleCursor(),true,!source)}</div></div><div class="nle-transport"><span class="mono" data-nle-time>${tc(nleCursor())}</span><div>${NB('start','skip-back','Zum Anfang',!timed)}${NB('prev','step-back','Ein Bild zurück',!timed)}${NB('play',S.playing?'pause':'play','Wiedergabe simulieren',!timed)}${NB('next','step-forward','Ein Bild vor',!timed)}${NB('end','skip-forward','Zum Ende',!timed)}</div><div class="nle-transport-buttons">${SXI('zoom','zoom-in','Vorschau vergrößern / einpassen')}${!source||source.type==='video'?SXI('capture','camera','Angezeigtes Frame als Medium sichern'):''}${source?'':SXI('compare','columns-2','Original vergleichen',S.studio.compare)}${SXI('theater','maximize','Viewer maximieren',S.studio.theater)}</div></div><div class="studio-viewer-note">${source?mediaTypes[source.type]:E(clipName(c))} · ${S.studio.aspect} · ${fps()} fps · Standbildsimulation</div>`;}
nleView=function(){if(S.mediaPreview&&selectedAsset()?.type==='text')return mediaDocumentView(selectedAsset());if(!S.nle.clips.length&&!S.mediaPreview)return `<div class="nle-empty"><b>Sequenz 01</b><p>Video, Bilder, Animationen und Audio aus den Quellen einsetzen.</p><div class="empty-actions">${SX('import-demo','Beispielmaterial importieren',{primary:true})}${B('workspace:media','Medien öffnen',{cls:'control'})}</div></div>`;return studioSequenceViewer();};
nleSeek=function(time,source=nleSource()){if(!S.nle)return;const t=Math.round(Math.max(0,Math.min(time,source?nleDuration():nleSpan()))*fps())/fps();S.nle[source?'sourceCursor':'cursor']=t;if(['edit','post'].includes(S.view)&&!(S.view==='post'&&S.studio.post==='review'))$('#nd-canvas').innerHTML=nleView();const line=$('.nle-playhead');if(line)line.style.left=S.nle.cursor/nleSpan()*100+'%';const scrub=$('[data-nle-scrub]');if(scrub)scrub.value=S.nle.cursor;paintIcons();};
nleSelect=function(id,time=null,multi=false){stop();const n=S.nle;if(!n.clips.some(c=>c.id===id))return;n.selectedTitle=null;n.marked=multi?(n.marked.includes(id)?n.marked.filter(x=>x!==id):[...n.marked,id]):[id];n.selected=n.marked.includes(id)?id:n.marked.at(-1)||null;S.studio.selectedKey=null;const c=nleClip();if(c?.shot!==undefined)S.selected=[c.shot];S.mediaPreview=false;if(c){if(time!==null&&c.id===id)n.cursor=time;else if(n.cursor<c.start||n.cursor>=c.start+nleLength(c))n.cursor=c.start;if(c.type==='audio'){n.tab='audio';if(S.view==='post')S.studio.post='audio';}else{if(n.tab==='audio')n.tab='video';if(S.view==='post'&&['titles','audio'].includes(S.studio.post))S.studio.post='color';}}render();persist();};
function studioClip(c){const selected=S.nle.marked.includes(c.id)||S.nle.selected===c.id,track=S.nle.tracks.find(x=>x.id===c.track);return `<div class="nle-clip ${selected?'selected':''} ${c.type==='audio'?'studio-audio-clip':''}" style="left:${c.start/nleSpan()*100}%;width:${nleLength(c)/nleSpan()*100}%"><button data-sx-clip="${c.id}" draggable="${S.view==='edit'&&!track?.lock}" aria-pressed="${selected}" aria-label="${E(clipName(c))}"><span class="nle-filmstrip">${c.type==='audio'?'<span class="studio-wave">▂▅▃▇▆▂▅▃▆▂▅▆▃▂▅▇▅▂▃▆▃▅▂</span>':clipImage(c)}</span><span class="nle-clip-label">${E(clipName(c))}${c.link?' ⛓':''}</span></button>${(S.view==='edit'&&!track?.lock?['in','out']:[]).map(edge=>`<button class="nle-trim nle-trim-${edge}" data-sx-trim="${edge}" data-sx-id="${c.id}" aria-label="${edge==='in'?'Anfang':'Ende'} trimmen" ${track?.lock||S.view!=='edit'?'disabled':''}></button>`).join('')}</div>`;}
nleTimeline=function(){const n=S.nle,span=nleSpan();return `<button class="nle-divider" data-nle-height aria-label="Timeline-Höhe ändern"></button><div class="edit-timeline"><div class="nle-toolbar"><b>Sequenz 01</b>${NB('tool-pointer','mouse-pointer-2','Auswahl · V',false,n.tool==='pointer')}${S.view==='edit'?NB('tool-razor','scissors','Rasierklinge · C',false,n.tool==='razor'):''}${S.view==='edit'?NB('split','split-square-horizontal','Am Abspielkopf teilen',!nleCanCut()):''}${SXI('snapping','magnet','Einrasten',n.snap)}${SXI('clip-menu','ellipsis','Clip- und Bereichsaktionen')}${NB('text','type','Titel hinzufügen')}${SXI('add-track','plus','Spur hinzufügen')}<span class="grow"></span><label class="nle-zoom">${NI('zoom-out')}<input data-nle-zoom type="range" min="1" max="4" step=".25" value="${n.zoom}" aria-label="Timeline-Zoom">${NI('zoom-in')}</label></div><div class="studio-timeline-scroll"><div class="studio-timeline" style="--tracks:${n.tracks.length}"><div class="studio-heads"><div class="nle-header-ruler">Spuren</div>${n.tracks.map(t=>`<div class="studio-track-head"><button data-do="studio:track-${t.id}">${t.id}</button>${SXI('track-hide-'+t.id,t.type==='audio'?(t.hidden?'volume-x':'volume-2'):(t.hidden?'eye-off':'eye'),'Spur '+t.id+(t.type==='audio'?' stummschalten':' ein-/ausblenden'),!t.hidden)}${SXI('track-lock-'+t.id,t.lock?'lock':'unlock','Spur '+t.id+' sperren',t.lock)}</div>`).join('')}</div><div class="nle-scroll"><div class="nle-content" style="width:${n.zoom*100}%"><div class="nle-ruler">${Array.from({length:Math.floor(span/2)+1},(_,i)=>`<span style="left:${i*2/span*100}%">${tc(i*2).slice(3,8)}</span>`).join('')}<input data-nle-scrub type="range" min="0" max="${span}" step="${1/fps()}" value="${n.cursor}" aria-label="Abspielkopf in der Timeline"></div>${n.tracks.map(t=>`<div class="nle-lane studio-lane ${t.hidden?'track-off':''}" data-sx-track="${t.id}">${n.clips.filter(c=>c.track===t.id).map(studioClip).join('')}${n.titles.map((x,i)=>x.track===t.id?`<button data-do="studio:title-${i}" class="nle-title-clip" aria-pressed="${n.selectedTitle===i}" style="left:${x.start/span*100}%;width:${(x.end-x.start)/span*100}%">${E(x.text)}</button>`:'').join('')}</div>`).join('')}<div class="nle-playhead" style="left:${n.cursor/span*100}%"><span></span></div>${n.showRange?`<div class="studio-range" style="left:${n.range[0]/span*100}%;width:${(n.range[1]-n.range[0])/span*100}%"></div>`:''}</div></div></div></div><div class="nle-timeline-footer"><span>${n.clips.length} Clips · ${tc(nleTotal())}</span><span data-nle-edit-note>${E(S.notice||(S.view==='edit'?'⌘ Mehrfachauswahl · Kanten trimmen · Quellen ziehen':'⌘ Mehrfachauswahl · Auswahl steuert Inspector'))}</span><span>${fps()} fps</span></div></div>`;};
const gradeFields={basic:[['Belichtung','exposure',-3,3,.1],['Kontrast','contrast',-100,100],['Lichter','highlights',-100,100],['Schatten','shadows',-100,100],['Schwarz','blacks',-100,100],['Weiß','whites',-100,100],['Temperatur','temperature',-100,100],['Tönung','tint',-100,100],['Dynamik','vibrance',-100,100],['Sättigung','saturation',0,200]],effects:[['Schärfe','sharpen',0,100],['Entrauschen','denoise',0,100],['Klarheit','clarity',-100,100],['Dunst entfernen','dehaze',0,100],['Weichzeichnung','blur',0,100],['Bewegungsunschärfe','motionBlur',0,100],['Winkel','blurAngle',0,360],['Vignette','vignette',0,100],['Mittelpunkt','vignetteMid',0,100],['Rundung','roundness',0,100],['Weiche Kante','feather',0,100],['Filmkorn','grain',0,100],['Korngröße','grainSize',0,100],['Leuchten','glow',0,100],['Radius','glowRadius',0,100],['Schwelle','threshold',0,100],['Wärme','warmth',0,100]],key:[['Key-Farbton','keyHue',0,360],['Toleranz','tolerance',0,100],['Weichheit','softness',0,100],['Farbsaum reduzieren','spill',0,100]]};
function gradeValue(c,k){return ['exposure','saturation'].includes(k)?c[k]:c.fx[k]||0;}
function gradeControls(c,list){return list.map(([label,k,min,max,step=1])=>`<label class="studio-slider"><span>${label}<output>${gradeValue(c,k)}</output></span><input type="range" data-grade="${k}" min="${min}" max="${max}" step="${step}" value="${gradeValue(c,k)}" aria-label="${label}"></label>`).join('');}
function studioCurve(c){const channel=S.studio.curveChannel||'RGB',points=c.fx['curve'+channel]||[0,25,50,75,100];return `<div class="studio-curve" role="img" aria-label="${channel}-Kurve"><svg viewBox="0 0 200 150"><path d="M0 150L200 0" stroke="#62636a" fill="none"/><polyline points="${points.map((v,i)=>i*50+','+(150-v*1.5)).join(' ')}" stroke="var(--nd-accent)" fill="none" stroke-width="2"/>${points.map((v,i)=>`<circle cx="${i*50}" cy="${150-v*1.5}" r="3" fill="currentColor"/>`).join('')}</svg></div>${sxSelect('Kanal','curveChannel',channel,['RGB','Rot','Grün','Blau','Hue → Hue','Hue → Sat','Hue → Luma'])}${points.map((v,i)=>sxInput(['Schwarz','Tiefen','Mitten','Höhen','Weiß'][i],'curve-'+i,v,'number','min="0" max="100"')).join('')}`;}
function studioWheels(c){return ['Schatten','Mitten','Lichter'].map((name,i)=>`<div class="studio-wheel-row"><div class="studio-wheel" style="--wheel-angle:${c.fx['wheelHue'+i]||0}deg"><i></i></div><div>${sxInput(name+' Farbton','fx-wheelHue'+i,c.fx['wheelHue'+i]||0,'number','min="0" max="360"')}${sxInput('Stärke','fx-wheelSat'+i,c.fx['wheelSat'+i]||0,'number','min="0" max="100"')}${sxInput('Helligkeit','fx-wheelLift'+i,c.fx['wheelLift'+i]||0,'number','min="-100" max="100"')}</div></div>`).join('');}
const keyLabels={opacity:'Deckkraft',scale:'Skalierung',x:'Position X',y:'Position Y',gain:'Lautstärke'};
