fixture=function(which,pack='Music Video'){oldFixture(['Postproduction','Export'].includes(which)?'Schnitt':which,pack);studioEnsure();if(which==='Postproduction'||which==='Export'){S.view=which==='Export'?'finish':'post';S.fixture=which;render();}};
const oldSwitchWorkspace=switchWorkspace;
switchWorkspace=function(target){if(target==='finish')S.finishSection='delivery';oldSwitchWorkspace(target);if(target==='post'){S.mediaPreview=false;render();}};
approve=function(){if(S.view==='takes'&&readiness()){S.done.takes=true;S.current='edit';S.have.edit=true;if(!S.nle?.clips.length&&!S.nle?.titles.length)S.nle=null;undo=[];redo=[];studioAudit('Takes freigegeben','Auswahl für die Montage bereit');switchWorkspace('edit');return;}oldApprove();};
finishReady=function(){return !S.running&&(S.finish.format==='ngv'||finishHasCut())&&(S.finish.format!=='video'||visibleVideo().length>0&&(!S.finish.requireReview||finishCurrentReview()));};
finishPicture=function(time){return studioPicture(studioVisualAt(time),time);};
finishFrameLabel=function(time){return clipName(studioVisualAt(time));};
finishStrip=function(){return `<div class="finish-filmstrip">${finishClips().map((c,i)=>`<button data-do="finish:clip-${i}" aria-pressed="${S.finish.cursor>=c.start&&S.finish.cursor<c.start+nleLength(c)}">${clipImage(c)}<span><b>${E(clipName(c))}</b><small class="mono">${tc(c.start)}</small></span></button>`).join('')}</div>`;};
const oldFinishAction=finishAction;
finishAction=function(command){if(command==='confirm-repair'){S.modal=null;const x=S.finish.findings.find(x=>x.id===S.finish.selectedFinding);switchWorkspace('edit');if(x?.clip)nleSelect(x.clip,x.time);return;}oldFinishAction(command);};
const oldFinishInspector=finishInspector;
finishInspector=function(){return oldFinishInspector().replace('Gesamtfilm mit Audio gesichtet','Gesamtfilm gesichtet · Audio im Produkt');};
function task(title,kind,detail,options=[]){stop();S.modal=null;S.studio.task={title,kind,detail,options,selected:['ai','repair','music','entity','frame'].includes(kind)?(options.length?[0]:[]):options.map((_,i)=>i),stage:'prepare',revision:S.version,context:finishDigest(),clip:S.nle.selected,shot:at(),entity:S.studio.entity,phase:S.view,input:'',id:Date.now()};render();persist();}
function taskBlock(t){if(t.kind==='model')return '';return t.revision!==S.version?'Projektstand geändert':t.context!==finishDigest()?'Schnitt oder Quellen geändert':S.cost+(t.cost||0)>S.cap?'Budget reicht nicht aus':'';}
function renderTask(){if(S.modal==='studio-model-research')dialog();const t=S.studio.task,el=$('#nd-task');el.hidden=!t||t.kind==='model';if(!t||t.kind==='model'){el.innerHTML='';if(t&&S.modal==='studio-model-research')dialog();return;}if(t.kind==='batch'){el.hidden=S.view!=='takes'||t.stage==='done';if(el.hidden){el.innerHTML='';return;}const count=t.selected.filter(i=>t.retake||!S.takes[i]?.length).length,blocked=t.stage==='review'?taskBlock(t):'';el.innerHTML=`<div class="take-order"><span><b>${count} Shots</b><small>${blocked|| (t.stage==='review'?'Beispielkosten: '+money(t.cost):'Auswahl direkt an den Shots')}</small></span><span class="grow"></span>${SX('task-close','Abbrechen',{cls:'control'})}${t.stage==='prepare'?SX('task-preview','Kosten prüfen…',{primary:true,disabled:!count}):SX('task-accept','Für '+money(t.cost)+' generieren',{primary:true,disabled:!!blocked||!count})}${blocked?SX('task-recheck','Neu prüfen',{cls:'control'}):''}</div>`;return;}el.innerHTML=`<div class="studio-task-head"><b>${E(t.title)}</b><span class="grow"></span>${SX('task-close',NI('x'),{attrs:'aria-label="Aufgabe schließen"'})}</div><div class="studio-task-body"><div class="studio-task-content"><p>${E(t.detail)}</p>${t.stage==='done'?'<small>Ergebnis übernommen · in Entscheidungen gespeichert</small>':t.options.length?`<div class="studio-task-options" role="group" aria-label="Auswahl">${t.options.map((o,i)=>`<label class="finish-check"><input type="${['ai','repair','music','entity','frame'].includes(t.kind)?'radio':'checkbox'}" name="task-choice" data-task-option="${i}" ${t.stage!=='prepare'?'disabled':''} ${t.selected.includes(i)?'checked':''}><span>${E(o)}</span></label>`).join('')}</div>`:''}${['ai','music','sfx','entity','organize','caption'].includes(t.kind)&&t.stage==='prepare'?`<label class="studio-task-input"><span>Ergänzung · optional</span><input data-task-input value="${E(t.input)}" placeholder="Nur wenn du etwas präzisieren möchtest"></label>`:''}</div><div class="studio-task-actions">${t.stage==='prepare'?SX('task-preview','Vorschlag prüfen',{primary:true,disabled:!!t.options.length&&!t.selected.length}):t.stage==='review'?SX('task-accept',t.cost?'Beispielkosten '+money(t.cost)+' freigeben':'Übernehmen',{primary:true,disabled:!!taskBlock(t)||!!t.error}):SX('task-close','Schließen',{cls:'control'})}${t.stage!=='done'?SX('task-close','Verwerfen',{cls:'control'}):''}${t.stage==='review'&&(taskBlock(t)||t.error)?`<small role="status">${E(t.error||taskBlock(t))}</small>${SX('task-recheck','Vorschlag neu prüfen',{cls:'control'})}`:''}<small>${t.stage==='review'?'Vorschau · noch nicht angewendet':'Strukturierter Auftrag · Simulation'}</small></div></div>`;paintIcons();}
function addDemoAsset(type='video',name=null){const i=S.mediaImports.length,id='free-'+Date.now()+'-'+i;S.mediaImports.push({id,name:name||({video:'Straße.mov',audio:'Atmosphäre.wav',image:'Lichtstudie.png',lottie:'Pfeil.lottie',text:'Notizen.txt'}[type]),type,folder:S.mediaFolder==='all'?'imports':S.mediaFolder,duration:['video','audio'].includes(type)?8:5,demoPic:['video','image'].includes(type)?i%6:undefined,content:type==='text'?'Die Maus repariert die Maschine. Licht: Morgen.':'',origin:'Import · Beispieldatei'});return id;}
function insertAsset(a,mode='insert'){if(!a||a.type==='text'||a.offline)return;const n=S.nle,kind=a.type==='audio'?'audio':'video',track=S.studio.targetTrack||n.tracks.find(t=>t.id===(kind==='audio'?'A1':'V1')&&!t.lock)?.id||n.tracks.find(t=>t.type===kind&&!t.lock)?.id;if(!track)return;checkpoint();let start=n.cursor,cin=S.studio.sourceIn||0,cout=S.studio.sourceOut||assetDuration(a)||5;cout=Math.min(cout,assetDuration(a)||5);if(cout<=cin)return;const duration=cout-cin;if(mode==='insert'){for(const c of [...n.clips]){if(c.start<start&&c.start+nleLength(c)>start&&!n.tracks.find(t=>t.id===c.track)?.lock&&(c.track===track||n.tracks.find(t=>t.id===c.track)?.sync)){const cut=c.in+(start-c.start)*c.speed;n.clips.push({...clone(c),id:'clip-'+n.nextId++,in:cut,start});c.out=cut;}}}if(mode==='insert')n.clips.filter(c=>c.start>=start&&!n.tracks.find(t=>t.id===c.track)?.lock&&(c.track===track||n.tracks.find(t=>t.id===c.track)?.sync)).forEach(c=>c.start+=duration);if(mode==='overwrite'){const end=start+duration,result=[];for(const c of n.clips){if(c.track!==track||c.start>=end||c.start+nleLength(c)<=start){result.push(c);continue;}const original=clone(c),ce=c.start+nleLength(c);if(c.start<start){c.out=c.in+(start-c.start)*c.speed;result.push(c);}if(ce>end)result.push({...original,id:'clip-'+n.nextId++,start:end,in:original.in+(end-original.start)*original.speed});}n.clips=result;}const c={...clipDefaults(),id:'clip-'+n.nextId++,asset:a.id,name:a.name,type:a.type,shot:a.shot,take:a.take,in:cin,out:cout,sourceDuration:assetDuration(a)||5,start,track};n.clips.push(c);n.selected=c.id;n.marked=[c.id];S.mediaPreview=false;nleChanged(mode==='overwrite'?'Quelle überschreibend eingesetzt':'Quelle eingefügt');}
function selectedClips(){const ids=S.nle.marked.length?S.nle.marked:[S.nle.selected];return S.nle.clips.filter(c=>ids.includes(c.id)&&!S.nle.tracks.find(t=>t.id===c.track)?.lock);}
nleAction=function(command){S.have.edit=true;if(S.view==='post'){if(S.studio.post==='review'&&['play','start','prev','next','end'].includes(command)){finishAction(command);return;}if(['split','trim-in','trim-out','tool-razor','insert'].includes(command))return;}if(command==='insert'){insertAsset(selectedAsset());return;}if(command==='text'||command==='title'){studioAction('title-add');return;}if(command==='original'){const c=nleClip();if(c?.shot!==undefined){visit('takes');choose(c.shot);}else if(c?.asset){S.mediaSelection=c.asset;revealMedia();}return;}oldNleAction(command);};
