 if(kind==='project-settings'){title='Projekteinstellungen';body=sxInput('Name','project-name',S.name)+sxSelect('Seitenverhältnis','aspect',t.aspect,['16:9','9:16','1:1','4:3'])+sxSelect('Auflösung','resolution',t.resolution,[[720,'720'],[1080,'1080'],[2160,'2160']])+sxSelect('Bildrate','fps',fps(),[[24,'24 fps'],[25,'25 fps'],[30,'30 fps'],[60,'60 fps']])+'<small>Viewer, Timeline und Export verwenden dieselben Projekteinstellungen.</small>';}
