  body=`<div class="studio-settings-tabs" role="group" aria-label="Einstellungsbereiche">${[['general','Allgemein'],['agent','Agent'],['providers','Provider'],['models','Modelle'],['packs','Format-Packs'],['storage','Speicher']].map(([id,name])=>SX('settings-'+id,name,{attrs:`aria-pressed="${t.settings===id}"`})).join('')}</div>`;
