  if(t.settings==='models')fields=settingsRow('Modelle',generationModels.map((m,i)=>sxCheck(m.provider+' · '+m.name,'model-'+i,!t.disabledModels.includes(i))).join(''))+settingsRow('',SX('model-research',t.modelEvidence?'Fähigkeiten erneut prüfen…':'Fähigkeiten prüfen…',{cls:'control'})+(t.modelEvidence?'<small>Demoprofil übernommen</small>':''));
