 if(command.startsWith('review-clip-')){const clip=n.clips.find(x=>x.id===command.slice(12));if(clip){S.finish.mode='film';S.finish.cursor=clip.start;render();persist();}return;}
 if(command.startsWith('clip-')&&command!=='clip-menu'){nleSelect(command.slice(5));return;}
 if(command.startsWith('search-')){t.search=command.slice(7);refreshPool();return;}
 if(command.startsWith('moment-')){const [id,index]=command.slice(7).split('~'),a=assets().find(x=>x.id===id),hit=a&&searchHits(a)[+index];if(!hit)return;S.mediaSelection=id;S.mediaMarked=[id];t.sourceIn=hit.in||0;t.sourceOut=hit.out||assetDuration(a)||5;S.mediaPreview=S.view!=='media';render();return;}
 if(command==='source-close'){S.mediaPreview=false;render();return;}
 if(command.startsWith('entity-filter-')){t.refCategory=command.slice(14);canvas();return;}
