 if(command.startsWith('shot-use-')){visit('plan');choose(+command.slice(9));return;}
 if(command.startsWith('beat-')){t.beat=+command.slice(5);canvas();return;}
 if(command.startsWith('title-')&&/^title-\d+$/.test(command)){selectTitle(+command.slice(6));return;}
 if(command.startsWith('key-')&&/^key-\d+$/.test(command)){t.selectedKey=+command.slice(4);n.cursor=c.start+c.keys[t.selectedKey].time;canvas();inspector();return;}
 if(command.startsWith('track-hide-')||command.startsWith('track-lock-')){const parts=command.split('-'),tr=n.tracks.find(x=>x.id===parts[2]);checkpoint();tr[parts[1]==='hide'?'hidden':'lock']=!tr[parts[1]==='hide'?'hidden':'lock'];refresh();return;}
 if(/^track-[VA]\d+$/.test(command)){t.track=command.slice(6);open('track');return;}
 if(command.startsWith('mcp-delete-')){t.connections.splice(+command.slice(11),1);dialog();return;}
 if(command.startsWith('open-recent-')){const name=command.slice(12);if(name==='Leeres Projekt')fixture('Leer','Generic');else if(t.projectSaved)restore(t.projectSaved);else fixture('Schnitt');S.modal=null;refresh();return;}
 if(command.startsWith('activity-show-')){const x=t.activity[+command.slice(14)];if(!x?.view)return;S.modal=null;visit(x.view);if(x.view==='post')S.studio.post=x.post||'color';const index=S.shots.findIndex(s=>s.id===x.shotID);if(index>=0&&['board','plan','blocking','refs','review','takes'].includes(x.view))S.selected=[index];render();return;}
 if(['project-settings','open-project','save-copy','activity','settings','mcp-add','asset-menu','asset-rename','asset-delete','asset-relink','asset-path','clip-menu','add-track','range','track','swap','help','layout','load-lut','intake','take-review','take-rescue','folder-delete'].includes(command)){if(command==='asset-rename')t.assetName=a?.name;if(command==='range')n.showRange=true;open(command);return;}
