 if(command==='track-remove'){if(n.clips.some(c=>c.track===t.track)||n.titles.some(x=>x.track===t.track))return;checkpoint();n.tracks=n.tracks.filter(x=>x.id!==t.track);S.modal=null;refresh();return;}
 if(command==='copy'){t.clipboard=clone(selectedClips());S.modal=null;studioCommit(t.clipboard.length+' Clips kopiert');return;}
 if(command==='paste'||command==='duplicate'){const list=command==='paste'?t.clipboard:selectedClips();if(!list?.length)return;checkpoint();const first=Math.min(...list.map(x=>x.start)),end=Math.max(...list.map(x=>x.start+nleLength(x))),start=command==='duplicate'?end:n.cursor;n.marked=[];list.forEach(x=>{const v={...clone(x),id:'clip-'+n.nextId++,start:start+x.start-first};n.clips.push(v);n.marked.push(v.id);});n.selected=n.marked[0];S.modal=null;refresh();return;}
 if(command==='delete'||command==='ripple'){const list=selectedClips();if(!list.length)return;checkpoint();const begin=Math.min(...list.map(x=>x.start)),end=Math.max(...list.map(x=>x.start+nleLength(x)));n.clips=n.clips.filter(c=>!list.includes(c));if(command==='ripple')n.clips.filter(c=>c.start>=end&&n.tracks.find(t=>t.id===c.track)?.sync&&!n.tracks.find(t=>t.id===c.track)?.lock).forEach(c=>c.start-=end-begin);n.selected=null;n.marked=[];S.modal=null;refresh();return;}
