 if(['ai','music','sfx','frame'].includes(q.kind)){const type=['music','sfx'].includes(q.kind)?'audio':q.kind==='frame'?'image':'video',id=addDemoAsset(type,q.title+' · Variante'+({audio:'.wav',image:'.png',video:'.mov'}[type]));const a=S.mediaImports.find(x=>x.id===id);if(q.kind==='frame'){a.folder='anchors';a.shot=q.shot;a.role=q.options[selected[0]];S.shots[q.shot].anchorVariant=id;S.anchorAccepted=S.anchorAccepted.filter(i=>i!==q.shot);changed();}a.origin='KI-Auftrag · Simulation';a.generated=true;a.generation={provider:S.generation?.provider||'fal.ai',model:'Demo-Fähigkeitsprofil',prompt:q.detail,reference:c?.asset||null,cost:q.cost};if(c&&q.options.some((x,i)=>x==='Ausgewählte Instanz ersetzen'&&selected.includes(i))){c.asset=id;c.name=a.name;}}
