function studioSet(key,value){const t=S.studio,c=nleClip(),n=S.nle;if(/^(clip-|fx-|curve-|keyValue|keyTime|keyInterpolation|bypass$|lut$)/.test(key)&&!clipEditable(c))return;if(key.startsWith('clip-')){if(!c||n.tracks.find(t=>t.id===c.track)?.lock)return;checkpoint();const k=key.slice(5);if(['in','out','track'].includes(k)&&n.marked.length>1)return;for(const clip of selectedClips().filter(x=>['gain','fadeIn','fadeOut','speed','in','out','track'].includes(k)||x.type!=='audio')){if(k==='in')clip.in=Math.max(0,Math.min(Number(value),clip.out-1/fps()));else if(k==='out')clip.out=Math.max(clip.in+1/fps(),Math.min(Number(value),frameDuration(clip)));else parameterSet(clip,k,value);}}
 else if(key.startsWith('title-')){if(!titleEditable())return;const title=n.titles[t.titleIndex||0];if(title){checkpoint();title[key.slice(6)]=value;if(title.end<=title.start)title.end=title.start+1/fps();}}
 else if(key.startsWith('fx-')){if(c&&!n.tracks.find(t=>t.id===c.track)?.lock){checkpoint();selectedClips().filter(x=>x.type!=='audio').forEach(x=>x.fx[key.slice(3)]=value);}}
 else if(key.startsWith('curve-')){if(c){checkpoint();const k='curve'+(t.curveChannel||'RGB');for(const x of selectedClips().filter(x=>x.type!=='audio')){x.fx[k]??=[0,25,50,75,100];x.fx[k][+key.slice(6)]=Math.max(0,Math.min(100,Number(value)));}}}
 else if(key==='bypass'){selectedClips().filter(x=>x.type!=='audio').forEach(x=>x.bypass=value);}
 else if(key==='lut'){selectedClips().filter(x=>x.type!=='audio').forEach(x=>x.fx.lut=value);}
 else if(key.startsWith('key')&&['keyValue','keyTime','keyInterpolation'].includes(key)){const x=c?.keys[t.selectedKey];if(x){checkpoint();x[{keyValue:'value',keyTime:'time',keyInterpolation:'interpolation'}[key]]=value;}}
 else if(key==='sourceIn'||key==='sourceOut'){const duration=assetDuration(selectedAsset())||5,frame=1/fps(),v=Math.round(Number(value)*fps())/fps();if(!Number.isFinite(v))return;t[key]=key==='sourceIn'?Math.max(0,Math.min(v,(t.sourceOut||duration)-frame)):Math.min(duration,Math.max(v,(t.sourceIn||0)+frame));}
 else if(key==='project-name')S.name=value;
 else if(key==='rangeIn'||key==='rangeOut'){n.range[key==='rangeIn'?0:1]=Number(value);n.range.sort((a,b)=>a-b);n.showRange=true;}
 else if(key.startsWith('track')){const tr=n.tracks.find(x=>x.id===t.track);if(tr&&{trackLock:'lock',trackHidden:'hidden',trackSync:'sync'}[key])tr[{trackLock:'lock',trackHidden:'hidden',trackSync:'sync'}[key]]=value;else t[key]=value;
 if(key==='blockoutTime')t.blockoutTime=Number(value);
 if(key==='generationMode'){t.generationEnd='';t.generationSource='';}if(key==='generationEnd')t.generationSource='';if(key==='generationSource')t.generationEnd='';
 if(key.startsWith('generation')||key.startsWith('provider-')||key.startsWith('model-'))generationQuote=null;}
 else if(key.startsWith('provider-'))t.providers[key.slice(9)]=value;
 else if(key.startsWith('model-')){const i=+key.slice(6);t.disabledModels=t.disabledModels.filter(x=>x!==i);if(!value)t.disabledModels.push(i);}
 else if(key.startsWith('shot-')){if(isEdit()&&shot()){checkpoint();shot()[key.slice(5)]=value;changed();}}
 else if(key.startsWith('entity-')){if(isEdit()){const e=t.entities[t.entity];if(e){checkpoint();if(key==='entity-name')e.name=value;else if(!e.locked.includes(key.slice(7)))e.attributes[key.slice(7)]=value;changed();}}}
 else if(key.startsWith('review-')||['takeDecision','takeNote'].includes(key)){const id=at()+'-'+t.takeFocus;t.takeReviews[id]??={checks:[],decision:'Freigeben',note:''};const r=t.takeReviews[id];if(key==='takeDecision')r.decision=value;else if(key==='takeNote')r.note=value;else{const i=+key.slice(7);r.checks=r.checks.filter(x=>x!==i);if(value)r.checks.push(i);}}
 else t[key]=value;
 if(key==='blockoutTime')t.blockoutTime=Number(value);
 if(key==='generationMode'){t.generationEnd='';t.generationSource='';}if(key==='generationEnd')t.generationSource='';if(key==='generationSource')t.generationEnd='';
 if(key.startsWith('generation')||key.startsWith('provider-')||key.startsWith('model-'))generationQuote=null;
}
