root.addEventListener('dragstart',e=>{const c=e.target.closest('[data-sx-clip]'),a=e.target.closest('[data-media-drag],[data-library-drag]');if(c&&(S.view!=='edit'||!clipEditable(S.nle.clips.find(x=>x.id===c.dataset.sxClip)))){e.preventDefault();return;}if(c){studioDrag={id:c.dataset.sxClip,duplicate:e.altKey};e.dataTransfer.setData('application/x-ngv-clip',c.dataset.sxClip);}if(a){studioSource=a.dataset.mediaDrag||a.dataset.libraryDrag;e.dataTransfer.setData('application/x-ngv-source',studioSource);}});
root.addEventListener('dragover',e=>{if((studioDrag||studioSource)&&e.target.closest('[data-sx-track]')){e.preventDefault();const scroll=$('.nle-scroll'),r=scroll.getBoundingClientRect();if(e.clientX>r.right-30)scroll.scrollLeft+=15;if(e.clientX<r.left+30)scroll.scrollLeft-=15;}});
root.addEventListener('drop',e=>{const el=e.target.closest('[data-sx-track]');if(!el||S.view!=='edit')return;const tr=S.nle.tracks.find(t=>t.id===el.dataset.sxTrack);if(tr.lock)return;const r=el.getBoundingClientRect();let time=Math.max(0,(e.clientX-r.left)/r.width*nleSpan());if(S.nle.snap){const points=[S.nle.cursor,...S.nle.clips.flatMap(c=>[c.start,c.start+nleLength(c)])],snap=points.find(t=>Math.abs(time-t)<.25);if(snap!==undefined)time=snap;}time=Math.round(time*fps())/fps();if(studioSource){const a=assets().find(a=>a.id===studioSource);if(!a||tr.type!==(a.type==='audio'?'audio':'video'))return;e.preventDefault();S.nle.cursor=time;S.studio.targetTrack=tr.id;insertAsset(a,e.shiftKey?'overwrite':'insert');S.studio.targetTrack=null;}else if(studioDrag){const c=S.nle.clips.find(c=>c.id===studioDrag.id);if(tr.type!==(c.type==='audio'?'audio':'video'))return;e.preventDefault();checkpoint();const delta=time-c.start,list=selectedClips().some(x=>x.id===c.id)?selectedClips():[c],linked=c.link?S.nle.clips.filter(x=>x.link===c.link&&!S.nle.tracks.find(t=>t.id===x.track)?.lock):list;if(linked.some(item=>{const dest=item===c?tr.id:item.track,begin=Math.max(0,item.start+delta);return S.nle.clips.some(x=>(studioDrag.duplicate||!linked.includes(x))&&x.track===dest&&x.start<begin+nleLength(item)&&x.start+nleLength(x)>begin);})){studioDrag=studioSource=null;S.notice='Ziel belegt · freie Stelle wählen oder Überschreiben verwenden';gate();bottom();return;}for(const item of linked){if(studioDrag.duplicate)S.nle.clips.push({...clone(item),id:'clip-'+S.nle.nextId++,track:item===c?tr.id:item.track,start:Math.max(0,item.start+delta)});else item.start=Math.max(0,item.start+delta);}if(!studioDrag.duplicate)c.track=tr.id;S.mediaPreview=false;render();persist();}studioDrag=studioSource=null;});
root.addEventListener('dragend',()=>studioDrag=studioSource=null);
root.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||S.modal)return;const cmd=e.metaKey||e.ctrlKey;if(cmd&&e.key.toLowerCase()==='s'){e.preventDefault();studioAction('save-project');return;}if(!['edit','post'].includes(S.view)||e.target.closest('#nd-browser')||S.mediaPreview)return;if(cmd&&['c','v','a'].includes(e.key.toLowerCase())){e.preventDefault();if(e.key.toLowerCase()==='a'){S.nle.marked=S.nle.clips.map(c=>c.id);S.nle.selected=S.nle.marked[0]||null;S.nle.selectedTitle=null;render();}else studioAction(e.key.toLowerCase()==='c'?'copy':'paste');}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();studioAction(e.shiftKey?'ripple':'delete');}});
action=function(command){if(command==='finish-section:review'){S.studio.post='review';switchWorkspace('post');return;}if(command==='media-import'){S.modal='media-import';oldAction(command);const select=$('#nd-media-kind');if(select)select.insertAdjacentHTML('beforeend','<option value="image">Lichtstudie.png</option><option value="lottie">Pfeil.lottie</option>');return;}if(command==='import-media-file'){checkpoint();const id=addDemoAsset($('#nd-media-kind').value);S.mediaSelection=id;S.mediaMarked=[id];S.mediaFilter='all';S.mediaQuery='';S.modal=null;studioCommit('Beispieldatei importiert');return;}oldAction(command);};
const oldSelectMedia=selectMedia;
selectMedia=function(id,multi=false,range=false){const a=assets().find(a=>a.id===id);if(a&&workspace()!=='media'&&S.mediaSelection!==id){S.studio.sourceIn=0;S.studio.sourceOut=assetDuration(a)||5;}oldSelectMedia(id,multi,range);};
const oldMediaFolders=mediaFolders;
mediaFolders=function(){return oldMediaFolders().filter(f=>!S.studio?.hiddenFolders?.includes(f.id));};
const oldGenerationDialog=generationDialog;
generationDialog=function(){const result=oldGenerationDialog(),m=generationModel();if(S.modal==='gen-form'&&m?.audioKind)result.body+=group('Audio',m.audioKind==='tts'?sxSelect('Stimme','generationVoice',S.studio.generationVoice||'Demo-Stimme',['Demo-Stimme','Demo-Stimme 2']):sxInput('Lyrics / Stil','generationLyrics',S.studio.generationLyrics||'')+sxCheck('Instrumental','generationInstrumental',S.studio.generationInstrumental),false);return result;};

// The provider catalog in this prototype is a fixture, never live capability evidence.
const generationInputs=()=>({mode:S.studio.generationMode,end:S.studio.generationEnd,source:S.studio.generationSource,trim:S.studio.generationTrim,voice:S.studio.generationVoice,lyrics:S.studio.generationLyrics,instrumental:S.studio.generationInstrumental});
const originalGenerationAction=generationAction;
generationAction=function(command){if(command==='run'&&generationQuote&&JSON.stringify(generationQuote.inputs)!==JSON.stringify(generationInputs()))return;if(command==='review'&&S.studio.providers[S.generation.provider]===false){S.notice='Provider in den Einstellungen deaktiviert';return;}originalGenerationAction(command);if(command==='review'&&generationQuote){generationQuote.inputs=generationInputs();dialog();}if(command==='open'&&S.modal==='gen-form')studioAudit('Manuelle Generierung geöffnet');};
restore=function(saved){if(saved?.schema===11)saved={...saved,schema:10,view:saved.view==='post'?'edit':saved.view};const ok=oldRestore(saved);if(ok){studioEnsure();render();}return ok;};
const studioActionCore=studioAction;
studioAction=function(command){if(S.running&&!['modal-close','activity','help','batch-stop'].includes(command)&&!command.startsWith('activity-show-'))return;if(command==='batch-stop'){clearTimeout(jobTimer);S.running=false;S.studio.task.stage='paused';bgFinish('paused','Fertige Takes bleiben erhalten');studioAudit('Auftrag unterbrochen','Fertige Ergebnisse bleiben erhalten');render();persist();return;}if(command==='batch-resume'){runStudioBatch();return;}studioActionCore(command);};
const studioSetCore=studioSet;
studioSet=function(key,value){if(S.running)return;studioSetCore(key,value);};
const renderTaskCore=renderTask;
renderTask=function(){renderTaskCore();const t=S.studio.task;if(!t)return;if(['running','paused'].includes(t.stage))$('#nd-task').innerHTML=`<div class="studio-task-head"><b>${E(t.title)}</b><span class="grow"></span><small>${t.completed||0} / ${t.targets.length} fertig</small></div><div class="studio-task-body"><div><progress max="${t.targets.length}" value="${t.completed||0}"></progress><p>${t.stage==='paused'?'Auftrag unterbrochen · bereits fertige Takes bleiben erhalten':'Providerlauf simuliert · Ergebnisse werden einzeln übernommen'}</p></div>${SX(t.stage==='paused'?'batch-resume':'batch-stop',t.stage==='paused'?'Verbleibende fortsetzen':'Rest stoppen',{cls:'control'})}</div>`;};
const applyTaskCore=applyTask;
applyTask=function(){if(S.modal==='studio-model-research'){applyTaskCore();return;}const q=S.studio.task;if(q?.kind==='batch'){if(q.stage!=='review'||S.view!=='takes'||!isEdit())return;if(q.revision!==S.version||q.context!==finishDigest()||S.cost+(q.cost||0)>S.cap||!productionQuoteValid(q))return;if(!q.selected.length)return;q.targets=q.selected.filter(i=>q.retake||!S.takes[i]?.length);q.completed=0;runStudioBatch();return;}applyTaskCore();};
function runStudioBatch(){const q=S.studio.task;if(!q||q.revision!==S.version||q.context!==finishDigest()||!productionQuoteValid(q)||S.cost+q.quote.rows.slice(q.completed||0).reduce((sum,r)=>sum+r.cost,0)>S.cap)return;undo=[];redo=[];S.running=true;q.stage='running';bgStart('Video-Takes','Ausgewählte Shots erzeugen','studio:batch-stop',q.targets.length);bgAI.done=q.completed||0;bgAI.items=q.targets.map(i=>S.shots[i].id+' · '+S.shots[i].name);render();const step=()=>{if(!S.running||S.studio.task!==q)return;const i=q.targets[q.completed||0];if(i===undefined){S.running=false;q.stage='done';bgFinish('complete','Alle ausgewählten Takes bereit');S.takeRevision=S.version;studioAudit('Videolauf abgeschlossen',q.completed+' Takes');render();persist();return;}if(q.revision!==S.version||!productionQuoteValid(q)||S.cost+(q.quote.rows.find(r=>r.i===i)?.cost||0)>S.cap){S.running=false;q.stage='paused';bgFinish('paused','Projektstand oder Budget prüfen');render();return;}S.takes[i]??=[];if(q.retake||!S.takes[i].length){const row=q.quote.rows.find(r=>r.i===i);S.takes[i].push(nextTake(i));S.cost+=row.cost;S.productionReceipts??={};S.productionReceipts[S.shots[i].id+'~'+S.takes[i].at(-1)]={model:q.quote.model,provider:q.quote.provider,duration:row.duration,cost:row.cost};}q.completed++;if(S.view==='takes'){canvas();paintIcons();}bgAI.done=q.completed;bgAI.detail='Shot '+S.shots[i].id+' fertig';renderBackground();renderTask();persist();jobTimer=setTimeout(step,450);};jobTimer=setTimeout(step,450);}
const actionCore=action;
action=function(command){if(command==='video-cost'){if(S.view!=='takes'||!isEdit())return;if(!S.have.takes)develop();task('Video-Takes vorbereiten','batch','Einträge prüfen; nur ausgewählte offene Shots rendern.',S.shots.map(s=>s.id+' · '+s.name));S.studio.task.selected=S.shots.map((_,i)=>i).filter(i=>!S.takes[i]?.length);renderTask();canvas();paintIcons();return;}if(command==='stop-job'&&S.studio.task?.stage==='running'){studioAction('batch-stop');return;}actionCore(command);};
const taskActionCore=studioAction;
studioAction=function(command){taskActionCore(command);if(command==='task-preview'&&S.modal!=='studio-model-research'&&S.studio.task?.kind==='batch'){const q=S.studio.task;q.cost=q.selected.filter(i=>!S.takes[i]?.length).length*.4;renderTask();}};
const renderCore=render;
render=function(){renderCore();if(S.nle.tracks.find(t=>t.id===nleClip()?.track)?.lock)$$('[data-sx^="clip-"],[data-grade],[data-sx^="fx-"],[data-sx^="curve-"]').forEach(el=>el.disabled=true);$$('[data-resize],[data-nle-height]').forEach(el=>el.disabled=false);if(S.running)$$('button,input,select,textarea').forEach(el=>{const c=el.dataset.do||'';if(!el.dataset.panel&&!el.dataset.resize&&!el.dataset.nleHeight&&!el.hasAttribute('data-open')&&!el.hasAttribute('data-shot')&&!el.hasAttribute('data-section')&&!/^(open:|mode:|ref:|segment:|moment:|sidebar:|wf:(audio-|refs-|compare-)|clay:(view-|shot-|output-|frame-|object-|endpoint-|inspect|plan|sketch)|background:|workspace:|studio:(batch-stop|modal-close|activity)|gen:cancel|stop-job|finish:cancel|close)/.test(c))el.disabled=true;});$$('[data-sx^="shot-"],[data-sx^="entity-"]').forEach(el=>el.disabled=el.disabled||!isEdit());if(!S.studio.ready&&workspace()==='production')$('#nd-gate').insertAdjacentHTML('afterbegin',`<div class="studio-backend" role="status">Agent nicht bereit ${SX('settings-agent','Agent-Einstellungen…',{cls:'control'})}</div>`);};
let persistSequence=0;
persist=async function(){try{const id=++persistSequence,saved=clone(S);saved.playing=false;saved.modal=null;saved.notice='';saved.studio.projectSaved=null;saved.studio.history=[];const bytes=new TextEncoder().encode(JSON.stringify(saved));let state=saved;if(bytes.length>14000&&globalThis.CompressionStream){const stream=new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'));const compressed=new Uint8Array(await new Response(stream).arrayBuffer());state={schema:11,packed:btoa(String.fromCharCode(...compressed))};}if(id!==persistSequence||JSON.stringify(state).length>14500)return;await window.openai?.setWidgetState?.({modelContent:{project:S.name,workspace:labels[S.view],pack:S.pack,phase:labels[S.current]},privateContent:state});}catch{}};
const restoreCore=restore;
restore=function(saved){if(saved?.packed){try{const bytes=Uint8Array.from(atob(saved.packed),c=>c.charCodeAt(0));new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text().then(text=>restore(JSON.parse(text))).catch(()=>{});return true;}catch{return false;}}const post=saved?.view==='post',ok=restoreCore(saved);if(ok){if(post)S.view='post';if(S.studio.task?.stage==='running'){S.studio.task.stage='paused';S.running=false;}render();}return ok;};

let pictureDrag=null;
root.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-picture-drag]'),c=nleClip();if(!el||S.mediaPreview||!S.studio.canvasEdit||!c||S.running||S.nle.tracks.find(t=>t.id===c.track)?.lock)return;checkpoint();const b=el.getBoundingClientRect();pictureDrag={id:c.id,x:e.clientX,y:e.clientY,cx:c.x,cy:c.y,w:b.width,h:b.height};el.setPointerCapture(e.pointerId);e.preventDefault();});
root.addEventListener('pointermove',e=>{if(!pictureDrag)return;const d=pictureDrag,c=S.nle.clips.find(c=>c.id===d.id);c.x=Math.round(d.cx+(e.clientX-d.x)/d.w*100);c.y=Math.round(d.cy+(e.clientY-d.y)/d.h*100);const el=$('[data-picture-drag]');el.style.setProperty('--clip-x',c.x+'%');el.style.setProperty('--clip-y',c.y+'%');});
root.addEventListener('pointerup',()=>{if(!pictureDrag)return;pictureDrag=null;render();persist();});

